// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./JinbaoProtocol.sol";

/**
 * @title DailyBurnManager
 * @dev 独立的每日燃烧管理合约，与主协议合约交互
 */
contract DailyBurnManager is Ownable {
    JinbaoProtocol public immutable protocol;
    IJBC public immutable jbcToken;
    
    uint256 public lastBurnTime;
    uint256 public constant BURN_INTERVAL = 24 hours;
    uint256 public constant BURN_PERCENTAGE = 100; // 1% = 100/10000
    
    event DailyBurnExecuted(uint256 burnAmount, uint256 timestamp, address executor);
    event BurnParametersUpdated(uint256 newInterval, uint256 newPercentage);
    
    constructor(address _protocol, address _jbcToken) Ownable(msg.sender) {
        protocol = JinbaoProtocol(_protocol);
        jbcToken = IJBC(_jbcToken);
        lastBurnTime = block.timestamp;
    }
    
    /**
     * @dev 执行每日燃烧 - 任何人都可以调用
     */
    function dailyBurn() external {
        require(block.timestamp >= lastBurnTime + BURN_INTERVAL, "Too early");
        
        // 获取当前JBC储备
        uint256 jbcReserve = protocol.swapReserveJBC();
        require(jbcReserve > 0, "No JBC to burn");
        
        // 计算燃烧数量 (1%)
        uint256 burnAmount = jbcReserve / 100;
        require(burnAmount > 0, "Burn amount too small");
        
        // 检查合约是否有足够的JBC代币来燃烧
        uint256 contractBalance = jbcToken.balanceOf(address(protocol));
        require(contractBalance >= burnAmount, "Insufficient JBC balance");
        
        // 更新最后燃烧时间
        lastBurnTime = block.timestamp;
        
        // 这里需要主合约支持外部燃烧调用
        // 由于当前主合约没有这个接口，我们只记录事件
        emit DailyBurnExecuted(burnAmount, block.timestamp, msg.sender);
    }
    
    /**
     * @dev 检查是否可以执行燃烧
     */
    function canBurn() external view returns (bool) {
        if (block.timestamp < lastBurnTime + BURN_INTERVAL) {
            return false;
        }
        
        uint256 jbcReserve = protocol.swapReserveJBC();
        if (jbcReserve == 0) {
            return false;
        }
        
        uint256 burnAmount = jbcReserve / 100;
        return burnAmount > 0;
    }
    
    /**
     * @dev 获取下次可燃烧时间
     */
    function nextBurnTime() external view returns (uint256) {
        return lastBurnTime + BURN_INTERVAL;
    }
    
    /**
     * @dev 获取可燃烧的JBC数量
     */
    function getBurnAmount() external view returns (uint256) {
        uint256 jbcReserve = protocol.swapReserveJBC();
        return jbcReserve / 100; // 1%
    }
    
    /**
     * @dev 获取距离下次燃烧的时间（秒）
     */
    function timeUntilNextBurn() external view returns (uint256) {
        uint256 nextBurn = lastBurnTime + BURN_INTERVAL;
        if (block.timestamp >= nextBurn) {
            return 0;
        }
        return nextBurn - block.timestamp;
    }
    
    /**
     * @dev 紧急暂停燃烧（仅限所有者）
     */
    function emergencyPause() external onlyOwner {
        lastBurnTime = type(uint256).max; // 设置为最大值，暂停燃烧
    }
    
    /**
     * @dev 恢复燃烧（仅限所有者）
     */
    function resumeBurn() external onlyOwner {
        lastBurnTime = block.timestamp;
    }
}

contracts/JBC.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract JBC is ERC20, Ownable {
    // Burn address
    address public constant BLACK_HOLE = 0x000000000000000000000000000000000000dEaD;
    
    // LP Pair address to identify buy/sell
    address public uniswapV2Pair;
    
    // Protocol Contract Address (Exempt from tax and can mint/burn)
    address public protocolAddress;

    // Taxes
    uint256 public constant BUY_TAX = 50; // 50%
    uint256 public constant SELL_TAX = 25; // 25%

    constructor(address initialOwner) ERC20("Jinbao Coin", "JBC") Ownable(initialOwner) {
        // Initial mint: 100 million
        // 5 million to LP (should be handled by deployer/protocol)
        // 95 million to Protocol for Mining
        _mint(msg.sender, 100_000_000 * 10**decimals());
    }

    function setPair(address _pair) external onlyOwner {
        uniswapV2Pair = _pair;
    }

    function setProtocol(address _protocol) external onlyOwner {
        protocolAddress = _protocol;
    }

    function _update(address from, address to, uint256 value) internal override {
        // Skip tax for owner, protocol, or if pair not set
        if (from == owner() || to == owner() || from == protocolAddress || to == protocolAddress || uniswapV2Pair == address(0)) {
            super._update(from, to, value);
            return;
        }

        uint256 taxAmount = 0;

        if (from == uniswapV2Pair) {
            // Buy
            taxAmount = (value * BUY_TAX) / 100;
        } else if (to == uniswapV2Pair) {
            // Sell
            taxAmount = (value * SELL_TAX) / 100;
        }

        if (taxAmount > 0) {
            // Burn the tax
            super._update(from, BLACK_HOLE, taxAmount);
            super._update(from, to, value - taxAmount);
        } else {
            super._update(from, to, value);
        }
    }

    // Allow protocol to burn tokens (e.g., daily deflation)
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }
}

contracts/JBCMigration.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title JBC Migration Contract
 * @dev 用于从旧 JBC 代币迁移到新 JBCv2 代币的合约
 * 
 * 功能:
 * - 1:1 比例代币兑换
 * - 安全的迁移流程
 * - 迁移统计和事件记录
 * - 紧急暂停功能
 */
contract JBCMigration is Ownable, ReentrancyGuard {
    
    // =============================================================================
    // 状态变量
    // =============================================================================
    
    IERC20 public immutable oldJBC;    // 旧 JBC 代币合约
    IERC20 public immutable newJBC;    // 新 JBCv2 代币合约
    
    bool public migrationEnabled;      // 迁移开关
    uint256 public totalMigrated;      // 总迁移数量
    uint256 public migrationCount;     // 迁移次数
    
    // 用户迁移记录
    mapping(address => uint256) public userMigrated;
    mapping(address => uint256) public userMigrationTime;
    
    // =============================================================================
    // 事件定义
    // =============================================================================
    
    event Migration(
        address indexed user,
        uint256 amount,
        uint256 timestamp
    );
    
    event MigrationEnabled(bool enabled);
    event EmergencyWithdraw(address token, uint256 amount);
    
    // =============================================================================
    // 构造函数
    // =============================================================================
    
    constructor(
        address _oldJBC,
        address _newJBC
    ) Ownable(msg.sender) {
        require(_oldJBC != address(0), "Invalid old JBC address");
        require(_newJBC != address(0), "Invalid new JBC address");
        
        oldJBC = IERC20(_oldJBC);
        newJBC = IERC20(_newJBC);
        migrationEnabled = true;
        
        emit MigrationEnabled(true);
    }
    
    // =============================================================================
    // 迁移功能
    // =============================================================================
    
    /**
     * @dev 迁移代币 (1:1 比例)
     * @param amount 迁移数量
     */
    function migrate(uint256 amount) external nonReentrant {
        require(migrationEnabled, "Migration disabled");
        require(amount > 0, "Amount must be greater than 0");
        
        // 检查用户旧代币余额
        uint256 userBalance = oldJBC.balanceOf(msg.sender);
        require(userBalance >= amount, "Insufficient old JBC balance");
        
        // 检查合约新代币余额
        uint256 contractBalance = newJBC.balanceOf(address(this));
        require(contractBalance >= amount, "Insufficient new JBC in contract");
        
        // 转移旧代币到合约
        require(
            oldJBC.transferFrom(msg.sender, address(this), amount),
            "Old JBC transfer failed"
        );
        
        // 转移新代币给用户
        require(
            newJBC.transfer(msg.sender, amount),
            "New JBC transfer failed"
        );
        
        // 更新统计
        userMigrated[msg.sender] += amount;
        userMigrationTime[msg.sender] = block.timestamp;
        totalMigrated += amount;
        migrationCount++;
        
        emit Migration(msg.sender, amount, block.timestamp);
    }
    
    /**
     * @dev 批量迁移 (为多个用户)
     * @param users 用户地址数组
     * @param amounts 迁移数量数组
     */
    function batchMigrate(
        address[] calldata users,
        uint256[] calldata amounts
    ) external onlyOwner nonReentrant {
        require(migrationEnabled, "Migration disabled");
        require(users.length == amounts.length, "Array length mismatch");
        require(users.length <= 100, "Too many users");
        
        uint256 totalAmount = 0;
        for (uint256 i = 0; i < amounts.length; i++) {
            totalAmount += amounts[i];
        }
        
        // 检查合约新代币余额
        uint256 contractBalance = newJBC.balanceOf(address(this));
        require(contractBalance >= totalAmount, "Insufficient new JBC in contract");
        
        for (uint256 i = 0; i < users.length; i++) {
            address user = users[i];
            uint256 amount = amounts[i];
            
            if (amount == 0) continue;
            
            // 检查用户旧代币余额
            uint256 userBalance = oldJBC.balanceOf(user);
            if (userBalance < amount) continue;
            
            // 转移旧代币到合约 (需要用户预先授权)
            if (oldJBC.transferFrom(user, address(this), amount)) {
                // 转移新代币给用户
                require(newJBC.transfer(user, amount), "New JBC transfer failed");
                
                // 更新统计
                userMigrated[user] += amount;
                userMigrationTime[user] = block.timestamp;
                totalMigrated += amount;
                migrationCount++;
                
                emit Migration(user, amount, block.timestamp);
            }
        }
    }
    
    // =============================================================================
    // 管理功能
    // =============================================================================
    
    /**
     * @dev 设置迁移开关
     * @param enabled 是否启用迁移
     */
    function setMigrationEnabled(bool enabled) external onlyOwner {
        migrationEnabled = enabled;
        emit MigrationEnabled(enabled);
    }
    
    /**
     * @dev 向合约充值新代币 (用于迁移)
     * @param amount 充值数量
     */
    function fundContract(uint256 amount) external onlyOwner {
        require(
            newJBC.transferFrom(msg.sender, address(this), amount),
            "Transfer failed"
        );
    }
    
    /**
     * @dev 紧急提取代币
     * @param token 代币地址
     * @param amount 提取数量
     */
    function emergencyWithdraw(address token, uint256 amount) external onlyOwner {
        require(token != address(0), "Invalid token address");
        
        IERC20(token).transfer(owner(), amount);
        emit EmergencyWithdraw(token, amount);
    }
    
    /**
     * @dev 销毁收集的旧代币
     * @param amount 销毁数量
     */
    function burnOldTokens(uint256 amount) external onlyOwner {
        uint256 balance = oldJBC.balanceOf(address(this));
        require(balance >= amount, "Insufficient balance");
        
        // 如果旧代币支持燃烧，调用 burn 函数
        // 否则发送到黑洞地址
        try IERC20(oldJBC).transfer(0x000000000000000000000000000000000000dEaD, amount) {
            // 成功发送到黑洞地址
        } catch {
            // 如果失败，保留在合约中
            revert("Burn failed");
        }
    }
    
    // =============================================================================
    // 视图函数
    // =============================================================================
    
    /**
     * @dev 获取迁移统计信息
     */
    function getMigrationStats() external view returns (
        uint256 totalMigrated_,
        uint256 migrationCount_,
        uint256 oldTokenBalance,
        uint256 newTokenBalance,
        bool enabled
    ) {
        return (
            totalMigrated,
            migrationCount,
            oldJBC.balanceOf(address(this)),
            newJBC.balanceOf(address(this)),
            migrationEnabled
        );
    }
    
    /**
     * @dev 获取用户迁移信息
     * @param user 用户地址
     */
    function getUserMigrationInfo(address user) external view returns (
        uint256 migrated,
        uint256 migrationTime,
        uint256 oldBalance,
        uint256 newBalance
    ) {
        return (
            userMigrated[user],
            userMigrationTime[user],
            oldJBC.balanceOf(user),
            newJBC.balanceOf(user)
        );
    }
    
    /**
     * @dev 检查用户是否可以迁移指定数量
     * @param user 用户地址
     * @param amount 迁移数量
     */
    function canMigrate(address user, uint256 amount) external view returns (
        bool canMigrate_,
        string memory reason
    ) {
        if (!migrationEnabled) {
            return (false, "Migration disabled");
        }
        
        if (amount == 0) {
            return (false, "Amount must be greater than 0");
        }
        
        uint256 userBalance = oldJBC.balanceOf(user);
        if (userBalance < amount) {
            return (false, "Insufficient old JBC balance");
        }
        
        uint256 contractBalance = newJBC.balanceOf(address(this));
        if (contractBalance < amount) {
            return (false, "Insufficient new JBC in contract");
        }
        
        uint256 allowance = oldJBC.allowance(user, address(this));
        if (allowance < amount) {
            return (false, "Insufficient allowance");
        }
        
        return (true, "Can migrate");
    }
    
    /**
     * @dev 获取迁移进度
     */
    function getMigrationProgress() external view returns (
        uint256 totalOldSupply,
        uint256 totalMigrated_,
        uint256 migrationPercentage,
        uint256 remainingToMigrate
    ) {
        // 注意: 这里假设旧代币有 totalSupply 函数
        try IERC20(oldJBC).totalSupply() returns (uint256 supply) {
            totalOldSupply = supply;
            totalMigrated_ = totalMigrated;
            
            if (totalOldSupply > 0) {
                migrationPercentage = (totalMigrated * 10000) / totalOldSupply; // 基点 (0.01%)
                remainingToMigrate = totalOldSupply - totalMigrated;
            }
        } catch {
            // 如果获取失败，返回 0
            totalOldSupply = 0;
            totalMigrated_ = totalMigrated;
            migrationPercentage = 0;
            remainingToMigrate = 0;
        }
        
        return (totalOldSupply, totalMigrated_, migrationPercentage, remainingToMigrate);
    }
}

contracts/JinbaoProtocol.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "./RedemptionLib.sol";

interface IJBC is IERC20 {
    function burn(uint256 amount) external;
}

contract JinbaoProtocol is Initializable, OwnableUpgradeable, UUPSUpgradeable, ReentrancyGuardUpgradeable {
    using RedemptionLib for RedemptionLib.RedeemParams;
    
    struct UserInfo {
        address referrer;
        uint256 activeDirects;
        uint256 teamCount;
        uint256 totalRevenue;
        uint256 currentCap;
        bool isActive;
        uint256 refundFeeAmount;
        uint256 teamTotalVolume;
        uint256 teamTotalCap;
        uint256 maxTicketAmount;
        uint256 maxSingleTicketAmount;
    }

    struct Stake {
        uint256 id;
        uint256 amount;
        uint256 startTime;
        uint256 cycleDays;
        bool active;
        uint256 paid;
    }

    struct Ticket {
        uint256 ticketId;
        uint256 amount;
        uint256 purchaseTime;
        bool exited;
    }

    struct PendingReward {
        address upline;
        uint256 amount;
    }

    struct DirectReferralData {
        address user;
        uint256 ticketAmount;
        uint256 joinTime;
    }

    IERC20 public mcToken;
    IJBC public jbcToken;
    
    address public marketingWallet;
    address public treasuryWallet;
    address public lpInjectionWallet;
    address public buybackWallet;
    
    uint256 public constant SECONDS_IN_UNIT = 60;
    
    uint256 public directRewardPercent;
    uint256 public levelRewardPercent;
    uint256 public marketingPercent;
    uint256 public buybackPercent;
    uint256 public lpInjectionPercent;
    uint256 public treasuryPercent;
    
    uint256 public redemptionFeePercent;
    uint256 public swapBuyTax;
    uint256 public swapSellTax;

    uint8 public constant REWARD_STATIC = 0;
    uint8 public constant REWARD_DYNAMIC = 1;
    uint8 public constant REWARD_DIRECT = 2;
    uint8 public constant REWARD_LEVEL = 3;
    uint8 public constant REWARD_DIFFERENTIAL = 4;

    mapping(address => UserInfo) public userInfo;
    mapping(address => Ticket) public userTicket;
    mapping(address => Stake[]) public userStakes;
    mapping(address => address[]) public directReferrals;
    mapping(uint256 => PendingReward[]) public ticketPendingRewards;
    
    struct LevelConfig {
        uint256 minDirects;
        uint256 level;
        uint256 percent;
    }
    LevelConfig[] public levelConfigs;
    
    uint256 public ticketFlexibilityDuration;
    bool public liquidityEnabled;
    bool public redeemEnabled;

    uint256 public swapReserveMC;
    uint256 public swapReserveJBC;
    
    uint256 public constant MIN_LIQUIDITY = 1000 * 1e18;
    uint256 public constant MAX_PRICE_IMPACT = 1000;

    uint256 public nextTicketId;
    uint256 public nextStakeId;
    uint256 public lastBurnTime;
    mapping(uint256 => address) public ticketOwner;
    mapping(uint256 => PendingReward[]) public stakePendingRewards;
    mapping(uint256 => address) public stakeOwner;
    uint256 public levelRewardPool;
    uint256[47] private __gap;
    bool public emergencyPaused;
    address public priceOracle;
    
    error InvalidAmount();
    error InvalidAddress();
    error InvalidRate();
    error InvalidTax();
    error InvalidFee();
    error InvalidCycle();
    error InvalidLevelConfig();
    error Unauthorized();
    error AlreadyBound();
    error SelfReference();
    error NotActive();
    error AlreadyExited();
    error Expired();
    error LowLiquidity();
    error InsufficientBalance();
    error NoRewards();
    error NothingToRedeem();
    error TransferFailed();
    error SumNot100();
    error TeamCountOverflow();
    error RecursionDepthExceeded();
    error InvalidTeamCountUpdate();
    error TeamCountMismatch(address user, uint256 expected, uint256 actual);
    error BatchUpdateSizeMismatch();
    error ContractPaused();
    error ActionTooEarly();
    error TransferFromFailed(string reason);
    error TransferFromFailedLowLevel();
    event BoundReferrer(address indexed user, address indexed referrer);
    event TicketPurchased(address indexed user, uint256 amount, uint256 ticketId);
    event TicketExpired(address indexed user, uint256 ticketId, uint256 amount);
    event LiquidityStaked(address indexed user, uint256 amount, uint256 cycleDays, uint256 stakeId);
    event FeeRefunded(address indexed user, uint256 amount);
    event RewardPaid(address indexed user, uint256 amount, uint8 rewardType);
    event RewardClaimed(address indexed user, uint256 mcAmount, uint256 jbcAmount, uint8 rewardType, uint256 ticketId);
    event ReferralRewardPaid(address indexed user, address indexed from, uint256 mcAmount, uint256 jbcAmount, uint8 rewardType, uint256 ticketId);
    event RewardCapped(address indexed user, uint256 amount, uint256 cappedAmount);
    event LevelRewardRecorded(uint256 indexed ticketId, address indexed upline, uint256 amount);
    event LevelRewardReleased(uint256 indexed ticketId, address indexed upline, uint256 amount);
    event LevelRewardPoolUpdated(uint256 amount, uint256 newTotal);
    event LevelRewardPoolWithdrawn(address indexed to, uint256 amount);
    event DifferentialRewardRecorded(uint256 indexed stakeId, address indexed upline, uint256 amount);
    event DifferentialRewardReleased(uint256 indexed stakeId, address indexed upline, uint256 amount);
    event DifferentialRewardDistributed(address indexed user, uint256 mcAmount, uint256 jbcAmount, uint256 jbcPrice, uint256 timestamp);
    event RewardTransferFailed(address indexed user, uint256 mcAmount, uint256 jbcAmount, string reason);
